import { readFile, writeFile } from "node:fs/promises";

const paths = {
  vik: new URL("../data/vik.json", import.meta.url),
  uzk: new URL("../data/uzk.json", import.meta.url),
  pvk: new URL("../data/pvk.json", import.meta.url)
};

const data = Object.fromEntries(await Promise.all(
  Object.entries(paths).map(async ([method, path]) => [method, JSON.parse(await readFile(path, "utf8"))])
));

const T = (title, content) => ({ type: "text", title, content });
const L = (title, items) => ({ type: "list", title, items });
const S = (title, items) => ({ type: "steps", title, items });
const W = (title, content) => ({ type: "warning", title, content });
const P = (title, content) => ({ type: "tip", title, content });

function upsert(method, item) {
  const index = data[method].findIndex(candidate => candidate.id === item.id);
  if (index >= 0) data[method][index] = { ...data[method][index], ...item };
  else data[method].push(item);
}

function group(method, { id, title, category, summary, order, tags }) {
  upsert(method, {
    id,
    type: "section",
    status: "published",
    title,
    sectionTitle: title,
    category,
    summary,
    description: summary,
    order,
    tags
  });
}

function practicalArticle(method, config) {
  const sections = [
    T("Назначение", config.purpose),
    ...(config.limit ? [W("Граница метода", config.limit)] : []),
    L(config.coreTitle || "Что необходимо учитывать", config.core),
    ...(config.extra || []),
    S(config.stepsTitle || "Практический порядок", config.steps),
    L("Что зафиксировать", config.record),
    L("Типичные ошибки", config.mistakes),
    P("Практический совет", config.tip),
    W("Оценка по документации", config.ntd || "Решение о допустимости принимают только по документации, применимой к конкретному объекту, соединению, стадии изготовления или эксплуатации. Справочная статья не заменяет установленную процедуру контроля.")
  ];
  upsert(method, {
    id: config.id,
    type: "article",
    parentId: config.parentId,
    order: config.order,
    status: "published",
    category: config.category,
    title: config.title,
    summary: config.summary,
    text: undefined,
    developmentNotice: undefined,
    plannedTitle: undefined,
    plannedMaterials: undefined,
    tags: [...new Set(config.tags)],
    sections
  });
}

// ВИК: сохраняем зрелый блок контроля и добавляем только отсутствующие уровни.
group("vik", { id: "vik-basics-section", title: "Основы и организация ВИК", category: "ОСНОВЫ ВИК", summary: "Назначение, возможности, ограничения, исходные документы и безопасная организация визуального и измерительного контроля.", order: 5, tags: ["вик", "основы вик", "организация контроля", "визуальный контроль"] });
group("vik", { id: "vik-evaluation-section", title: "Оценка и оформление результатов", category: "РЕЗУЛЬТАТЫ ВИК", summary: "Порядок сопоставления наблюдений с применимой НТД, фиксации ограничений и оформления результатов ВИК.", order: 18, tags: ["вик", "оценка", "оформление результатов", "акт вик", "журнал контроля"] });

